## 4. Detailed File Changes

### 4.1 `src/chatbot/chatApp.ts` — Container Mode Refactor

```typescript
// NEW: Options interface
export interface ChatAppOptions {
  /** When true, suppress header/statusBar/footer and expose `container` for embedding. */
  containerMode?: boolean;
  /** Parent renderable for the model selector overlay (defaults to renderer.root). */
  overlayParent?: BoxRenderable;
}

// MODIFIED: Constructor signature
constructor(renderer: CliRenderer, systemPrompt: string, options?: ChatAppOptions) {
  // ...
  const containerMode = options?.containerMode ?? false;

  // Container for tab mode (no chrome)
  this.container = new BoxRenderable(renderer, {
    id: 'chatbot-tab-container',
    width: '100%',
    height: '100%',
    flexDirection: 'column',
    backgroundColor: Theme.background,
  });

  if (!containerMode) {
    // Existing: create headerBox, statusBar, footerBox
    // Add to this.rootBox (existing behavior)
    renderer.root.add(this.rootBox);
  } else {
    // Container mode: only chatScroll + inputBox
    this.container.add(this.chatScroll);
    this.container.add(this.inputBox);
    // Don't add to renderer.root — the hub tab will add container to workspaceBox
  }

  // ModelSelector overlay
  const overlayParent = options?.overlayParent ?? renderer.root;
  overlayParent.add(this.modelSelector.overlay);
}

// NEW: Expose container for tab embedding
readonly container: BoxRenderable;
```

**Key insight:** `rootBox` remains for standalone mode. `container` is a new property used in container mode. In standalone mode, `container` can alias `rootBox` or be unused.

### 4.2 `src/hub/tabs/chatbot/tab.ts` — Adapter Class

```typescript
import type { BoxRenderable, CliRenderer, KeyEvent } from '@opentui/core';
import { ChatApp, type ChatAppOptions } from '../../../chatbot/chatApp.js';
import { initDb as initChatbotDb, closeDb as closeChatbotDb } from '../../../chatbot/db.js';
import { buildSystemPrompt } from '../../../chatbot/systemPrompt.js';
import type { AppShellTab } from '../../types.js';

export class ChatbotTab implements AppShellTab {
  readonly id = 'chatbot';
  readonly name = 'Chat';
  readonly container: BoxRenderable;

  private chatApp: ChatApp | null = null;
  private renderer: CliRenderer;
  private initialized = false;

  constructor(renderer: CliRenderer) {
    this.renderer = renderer;
    // Placeholder container — replaced in init() when ChatApp is created
    this.container = new BoxRenderable(renderer, {
      id: 'chatbot-placeholder',
      width: '100%',
      height: '100%',
    });
  }

  async init(): Promise<void> {
    if (this.initialized) return;

    await initChatbotDb();
    const systemPrompt = await buildSystemPrompt();

    // Create a wrapper box that will hold the chatApp container
    const wrapper = new BoxRenderable(this.renderer, {
      id: 'chatbot-tab-container',
      width: '100%',
      height: '100%',
      flexDirection: 'column',
    });

    const options: ChatAppOptions = {
      containerMode: true,
      overlayParent: /* needs hub's rootBox — see note below */,
    };

    this.chatApp = new ChatApp(this.renderer, systemPrompt, options);
    wrapper.add(this.chatApp.container);

    // Replace placeholder content
    this.container.add(wrapper);
    this.initialized = true;
  }

  focus(): void {
    this.chatApp?.focus();
  }

  cycleFocus(): void {
    // ChatApp handles its own Tab cycling (input ↔ scroll)
    this.chatApp?.handleKeyPress(/* synthetic tab event */);
  }

  isInputFocused(): boolean {
    return this.chatApp?.promptInput.focused ?? false;
  }

  blurInput(): void {
    this.chatApp?.promptInput.blur();
  }

  handleKeyPress(event: KeyEvent): boolean {
    if (!this.chatApp) return false;

    // Don't pass Escape to chatbot when not processing — let hub handle shutdown
    if (event.name === 'escape' && !this.chatApp['isProcessing']) {
      return false;
    }

    return this.chatApp.handleKeyPress(event);
  }

  getStatusLine(): string {
    // Show current model in hub footer
    return `Model: ${getModel()}`;
  }
}
```

**Note on overlay parent:** The tab's `create(renderer)` receives the `CliRenderer`. The overlay needs to be added to a renderable that covers the full screen. The simplest approach: add to `renderer.root` directly (same as standalone mode). This works because the hub's `rootBox` is already a child of `renderer.root`, so adding the overlay to `renderer.root` places it on top of everything.

